const INDEX_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#050505\"><meta name=\"description\" content=\"GLAMOUR LUXE \u2014 a premium profile discovery and visibility platform.\"><meta name=\"robots\" content=\"index,follow\">\n<title>GLAMOUR LUXE \u2014 Premium Profiles</title>\n<style>\n:root{--bg:#050505;--card:#0d0d0d;--gold:#d4af37;--gold2:#f5dc85;--green:#19a866;--muted:#a7a7a7}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#f5f1e7;font-family:Arial,sans-serif}\nbutton,input,select,textarea{font:inherit}button{cursor:pointer}.nav{height:78px;display:flex;align-items:center;gap:15px;padding:0 5%;position:sticky;top:0;z-index:20;background:#050505ee;border-bottom:1px solid #29251b;backdrop-filter:blur(14px)}\n.logo{width:245px;height:66px;object-fit:contain;margin-right:auto;animation:float 4.5s ease-in-out infinite,glow 3.6s ease-in-out infinite}@keyframes float{50%{transform:translateY(-4px)}}@keyframes glow{50%{filter:brightness(1.14) drop-shadow(0 0 12px #d4af3770)}}\n.nav button{background:none;border:0;color:#ddd;padding:9px}.nav button:hover{color:var(--gold)}.btn{border:1px solid var(--gold);background:transparent;color:var(--gold);border-radius:7px;padding:11px 17px}.btn:hover{box-shadow:0 0 18px #d4af3730}.gold{background:linear-gradient(135deg,var(--gold2),var(--gold));color:#111;border:0;font-weight:bold}\n.hero{min-height:490px;padding:70px 7%;display:flex;align-items:center;background:linear-gradient(90deg,#050505 0,#050505dd 37%,#05050520 78%),url(\"data:image/jpeg;base64,\") center/cover}\n.eyebrow{letter-spacing:5px;color:#d9bf70;font-size:12px}.hero h1{font:clamp(55px,8vw,102px) Georgia;margin:10px 0 0;color:#f0da94;text-shadow:0 0 30px #d4af3730}.hero h2{font:37px Georgia;margin:0}.hero p{color:#bbb;font-size:18px}\n.search{display:grid;grid-template-columns:repeat(4,1fr) 1.2fr auto;gap:9px;padding:18px 5%;background:#080808;border-block:1px solid #272115}.search label{display:block;color:#777;font-size:10px;letter-spacing:1.5px;margin-bottom:5px}.search input,.search select{width:100%;background:#111;color:#eee;border:1px solid #4a3b18;padding:12px;border-radius:7px}\n.section{padding:46px 5%}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.head h2{font:34px Georgia;margin:0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}\n.card{background:linear-gradient(180deg,#111,#0a0a0a);border:1px solid #29261e;border-radius:13px;overflow:hidden;transition:.25s}.card:hover{transform:translateY(-5px);border-color:#80671f;box-shadow:0 18px 35px #000}.photo{height:350px;background:#171717 center/cover no-repeat;position:relative}.badges{position:absolute;left:12px;top:12px}.badge{display:inline-block;padding:5px 8px;border-radius:5px;font-size:11px;margin-right:5px}.verified{background:var(--green);color:#fff}.vip{background:var(--gold);color:#111}.body{padding:16px}.name{font:26px Georgia;margin:0 0 6px}.meta{color:#999;font-size:14px}.price{color:var(--gold2);font-weight:bold;font-size:18px;margin:11px 0}.about{color:#c5c5c5;line-height:1.5;font-size:14px}.services{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.service{font-size:11px;border:1px solid #4a3b1b;color:#d8bf70;border-radius:20px;padding:5px 8px}.actions{display:flex;gap:8px}.actions button{flex:1}\n.page{display:none}.page.active{display:block}.tabbtn{border:0;background:none;color:#aaa;padding:10px 13px}.tabbtn.active{color:#d4af37;border-bottom:2px solid #d4af37}.modal{position:fixed;inset:0;background:#000d;display:none;align-items:center;justify-content:center;padding:20px;z-index:50}.modal.show{display:flex}.modalbox{width:min(700px,100%);max-height:90vh;overflow:auto;background:#111;border:1px solid var(--gold);border-radius:12px;padding:26px;position:relative}.close{position:absolute;right:10px;top:7px;background:none;border:0;color:#aaa;font-size:28px}.detail-photo{height:430px;background:center/cover;border-radius:10px}.muted{color:var(--muted)}.toast{position:fixed;right:18px;bottom:18px;background:#17140d;border:1px solid var(--gold);padding:13px 17px;border-radius:8px;display:none;z-index:70}.toast.show{display:block}footer{padding:30px 5%;border-top:1px solid #222;text-align:center;color:#777}\n@media(max-width:900px){.nav button:not(.gold){display:none}.grid{grid-template-columns:repeat(2,1fr)}.search{grid-template-columns:1fr 1fr}.logo{width:205px}}@media(max-width:600px){.grid,.search{grid-template-columns:1fr}.hero{padding:45px 6%}.hero h2{font-size:28px}}\n\n/* GLAMOUR LUXE final responsive polish */\nhtml{scroll-behavior:smooth}body{min-width:320px;overflow-x:hidden}.nav{gap:8px}.nav button{white-space:nowrap}.hero h1{font-family:Georgia,serif;font-size:clamp(46px,7vw,86px);letter-spacing:.08em;margin:8px 0}.hero h2{font-size:clamp(18px,2.2vw,28px);letter-spacing:.24em;color:#d4af37}.hero p{font-size:16px;letter-spacing:.18em;color:#c7c1b5}.section{max-width:1240px;margin:0 auto;padding:56px 5%}.search{max-width:1240px;margin:0 auto;padding:20px 5%;display:grid;grid-template-columns:repeat(5,1fr) auto;gap:10px;background:#090909;border:1px solid #282117;border-radius:16px}.search label{display:block;font-size:10px;letter-spacing:.15em;color:#9b9078;margin-bottom:6px}.search input,.search select{width:100%;min-height:44px;background:#0e0e0e;color:#eee;border:1px solid #3a301f;border-radius:9px;padding:10px}.card{transition:transform .2s ease,box-shadow .2s ease,border-color .2s ease}.card:hover{transform:translateY(-4px);border-color:#6d5924;box-shadow:0 18px 50px #0008}.photo{min-height:390px}.actions{display:flex;gap:8px;flex-wrap:wrap}.production-status{border-bottom:1px solid #2b2417;padding:7px 5%;font-size:12px;background:#090909;color:#cfc7b4}.mobile-note{display:none}@media(max-width:980px){.nav{height:auto;min-height:72px;flex-wrap:wrap;padding:10px 4%}.logo{width:180px;height:52px}.nav button{font-size:13px}.search{grid-template-columns:repeat(2,1fr)}.search .btn{grid-column:1/-1}.grid{grid-template-columns:repeat(2,1fr)!important}}@media(max-width:620px){.nav{position:relative}.logo{width:155px}.nav button{font-size:12px;padding:7px 5px}.hero{min-height:430px;padding:55px 6%}.hero p{letter-spacing:.08em}.search{grid-template-columns:1fr;padding:16px 5%}.search .btn{grid-column:auto}.grid{grid-template-columns:1fr!important}.photo{min-height:330px}.section{padding:38px 5%}.modalbox{padding:18px}.detail-photo{height:300px}.plan-card{padding:22px}.mobile-note{display:block}}\n</style>\n<style>\n.admin-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:22px;margin-top:18px}\n.admin-card{overflow:hidden;border:1px solid #3b2c12;border-radius:18px;background:linear-gradient(145deg,#101010,#080808);box-shadow:0 18px 45px #0008}\n.admin-photo-wrap{height:270px;position:relative;background:#121212;overflow:hidden}\n.admin-photo{width:100%;height:100%;object-fit:cover;display:block;transition:transform .45s ease;object-position:center 25%}\n.admin-card:hover .admin-photo{transform:scale(1.035)}\n.admin-photo-fallback{display:none;align-items:center;justify-content:center;height:100%;font:700 24px Georgia;color:#d4af37;letter-spacing:5px}\n.admin-badges{position:absolute;left:14px;bottom:14px;display:flex;gap:8px;flex-wrap:wrap}\n.admin-body{padding:18px}.admin-title-row{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:15px}.admin-title-row h3{margin:0 0 5px;font:700 24px Georgia;color:#f5dc85}.admin-status{font-size:10px;letter-spacing:1.5px;color:#78d89b;border:1px solid #285b3a;border-radius:20px;padding:6px 9px}\n.admin-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.admin-fields label{font-size:11px;letter-spacing:.8px;color:#a89d87}.admin-fields .full{grid-column:1/-1}.admin-fields input,.admin-fields textarea{width:100%;box-sizing:border-box;margin-top:5px}.admin-fields textarea{min-height:92px;resize:vertical}\n.admin-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:13px}\n@media(max-width:600px){.admin-grid{grid-template-columns:1fr}.admin-photo-wrap{height:300px}.admin-fields{grid-template-columns:1fr}.admin-fields .full{grid-column:auto}}\n</style>\n\n<meta name=\"description\" content=\"GLAMOUR LUXE \u2014 premium profile discovery platform with elegant verified profiles and private owner administration.\">\n<meta name=\"robots\" content=\"index,follow,max-image-preview:large\">\n<meta name=\"theme-color\" content=\"#050505\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:title\" content=\"GLAMOUR LUXE \u2014 Premium Profiles\">\n<meta property=\"og:description\" content=\"Discover premium profiles in an elegant black-and-gold experience.\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<link rel=\"canonical\" href=\"https://damp-glade-e297.axrarovabaxor93.workers.dev/\">\n<link rel=\"icon\" href=\"favicon.svg\">\n\n\n<!-- GLAMOUR_PRODUCTION_CONFIG -->\n<script>\n/*\n GLAMOUR production connection scaffold.\n Fill these values only after creating the Supabase project.\n Never put a service-role/secret key in this file.\n*/\nwindow.GLAMOUR_CONFIG = {\n  SUPABASE_URL: \"https://ifxpcofseejzobrueqvs.supabase.co\",\n  SUPABASE_PUBLISHABLE_KEY: \"sb_publishable_RBXrPe56Z76WP0b6wnzVDA_-wQJX7bP\"\n};\n</script>\n\n\n<style id=\"glamour-production-css\">\n.production-status{margin:16px 0;padding:14px 16px;border:1px solid #d4af3744;border-radius:14px;background:#0a0a0a;color:#ddd}\n.production-status strong{color:#d4af37}.production-status small{display:block;color:#999;margin-top:5px}\n.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:24px}.plan-card{background:linear-gradient(180deg,#111,#080808);border:1px solid #332914;border-radius:18px;padding:28px;position:relative;overflow:hidden}.plan-card.vip{border-color:#d4af37;box-shadow:0 0 28px #d4af3718}.plan-card h3{font:28px Georgia;margin:0 0 8px}.plan-price{font-size:36px;color:#d4af37;font-weight:700;margin:12px 0}.plan-card ul{padding-left:20px;color:#bbb;line-height:1.9}.plan-select{width:100%;padding:12px;background:#0b0b0b;color:#fff;border:1px solid #4a3b18;border-radius:8px;margin:8px 0 14px}@media(max-width:800px){.plan-grid{grid-template-columns:1fr}}\n</style>\n\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2\"></script>\n\n<script id=\"glamour-supabase-boot\">\n(function(){\n  const cfg=window.GLAMOUR_CONFIG||{};\n  if(!window.supabase || !cfg.SUPABASE_URL || !cfg.SUPABASE_PUBLISHABLE_KEY) return;\n  window.glamourDB=window.supabase.createClient(\n    cfg.SUPABASE_URL,\n    cfg.SUPABASE_PUBLISHABLE_KEY,\n    {auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}\n  );\n  window.glamourDBApi={\n    async listProfiles(){\n      const {data,error}=await glamourDB.from(\"profiles\").select(\"*\").eq(\"active\",true).order(\"created_at\",{ascending:false});\n      if(error) throw error; return data||[];\n    }\n  };\n})();\n</script>\n\n</head>\n<body>\n\n<div class=\"production-status\" id=\"productionStatus\">\n  <strong>GLAMOUR LUXE</strong> \u2014 live-site connection ready.\n  <small>Production database connection is active.</small>\n</div>\n\n<header class=\"nav\"><img loading=\"lazy\" onerror=\"this.style.opacity=0.25\" class=\"logo\" src=\"data:image/jpeg;base64,\" alt=\"GLAMOUR logo\">\n<button data-page=\"home\">Home</button><button data-page=\"profiles\">Explore Profiles</button><button data-page=\"vip\">VIP</button><button data-page=\"pricing\">Plans & Payment</button><button data-page=\"create\">Create Profile</button><button id=\"login\">Login</button><button id=\"signup\" class=\"btn gold\">Sign Up</button><button id=\"adminBtn\" style=\"display:none\" data-page=\"admin\">Admin</button></header>\n<main><div class=\"mobile-note muted\" style=\"padding:12px 5%\">Optimized for mobile and desktop.</div>\n<section id=\"home\" class=\"page active\"><div class=\"hero\"><div><div class=\"eyebrow\">DISCOVER PREMIUM PROFILES</div><h1>GLAMOUR LUXE</h1><h2>PREMIUM PROFILES</h2><p>Curated \u2022 Verified \u2022 Worldwide</p><button class=\"btn\" data-page=\"profiles\">Explore Profiles \u2192</button></div></div>\n<div class=\"search\"><div><label>LOCATION</label><select id=\"city\"><option value=\"\">Any city</option><option>Bangkok</option><option>Phuket</option><option>Pattaya</option></select></div><div><label>NATIONALITY</label><select id=\"nat\"><option value=\"\">Any</option><option>Thai</option><option>International</option></select></div><div><label>TYPE</label><select id=\"type\"><option value=\"\">Any</option><option>Verified</option><option>VIP</option></select></div><div><label>PLAN</label><select id=\"price\"><option value=\"\">Any</option><option value=\"mid\">Premium</option><option value=\"high\">VIP</option></select></div><div><label>NAME</label><input id=\"query\" placeholder=\"Search\"></div><button class=\"btn gold\" id=\"searchBtn\">Search</button></div>\n<section class=\"section\"><div class=\"head\"><h2>Featured Profiles</h2><button class=\"btn\" data-page=\"profiles\">View All \u2192</button></div><div id=\"featured\" class=\"grid\"></div></section></section>\n<section id=\"profiles\" class=\"page section\"><div class=\"head\"><h2>Explore Profiles</h2><button class=\"btn\" data-page=\"create\">Create Profile</button></div><div id=\"all\" class=\"grid\"></div></section>\n<section id=\"vip\" class=\"page section\"><h2>VIP Profiles</h2><div id=\"vips\" class=\"grid\"></div></section>\n<section id=\"pricing\" class=\"page section\">\n  <div class=\"head\"><div><h2>Plans & Payment</h2><p class=\"muted\">Choose a profile and activate its visibility plan securely through Stripe.</p></div></div>\n  <div id=\"paymentProfileWrap\" style=\"max-width:600px;margin-bottom:18px\"></div>\n  <div class=\"plan-grid\">\n    <article class=\"plan-card\"><h3>Basic</h3><div class=\"plan-price\">Free</div><ul><li>Standard listing</li><li>Basic profile information</li><li>Standard placement</li></ul><button class=\"btn\" onclick=\"setBasicPlan()\">Use Basic</button></article>\n    <article class=\"plan-card\"><h3>Premium</h3><div class=\"plan-price\">$19</div><small class=\"muted\">30 days \u00b7 editable in Stripe</small><ul><li>Premium badge</li><li>Featured placement</li><li>More profile visibility</li></ul><button class=\"btn gold\" onclick=\"buyPlan('premium')\">Pay & Activate</button></article>\n    <article class=\"plan-card vip\"><span class=\"badge vip\">\u265b VIP</span><h3 style=\"margin-top:14px\">VIP</h3><div class=\"plan-price\">$49</div><small class=\"muted\">30 days \u00b7 editable in Stripe</small><ul><li>VIP badge</li><li>Top featured placement</li><li>Maximum platform visibility</li></ul><button class=\"btn gold\" onclick=\"buyPlan('vip')\">Pay & Activate VIP</button></article>\n  </div>\n  <p class=\"muted\" style=\"margin-top:22px\">Payments are handled by Stripe Checkout; card details are not stored by GLAMOUR LUXE.</p>\n</section>\n<section id=\"create\" class=\"page section\"><h2>Create Profile</h2><div style=\"background:#0d0d0d;border:1px solid #332914;border-radius:12px;padding:24px\"><p class=\"muted\">Create a profile draft. Authentication, moderation and payments are connected in the production backend.</p><input placeholder=\"Profile name\" style=\"width:100%;padding:12px;background:#111;color:#fff;border:1px solid #4a3b18;border-radius:7px\"><br><br><button class=\"btn gold\" onclick=\"toast('Draft saved')\">Save Draft</button></div></section>\n\n<section id=\"admin\" class=\"page section\">\n  <div class=\"head\"><h2>Private Admin Panel</h2><div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn\" onclick=\"renderAdmin()\">Refresh</button><button id=\"dbTestBtn\" class=\"btn gold\" onclick=\"syncDemoProfilesToSupabase()\">Sync to Database</button></div></div>\n  <div class=\"panel\">\n    <p class=\"muted\" id=\"adminModeText\">Secure owner panel. Profile changes are saved to Supabase when connected.</p>\n    <div id=\"adminList\"></div>\n  </div>\n</section>\n</main><footer>\u00a9 2026 GLAMOUR LUXE \u2022 Premium Profile Platform</footer>\n<div id=\"modal\" class=\"modal\"><div class=\"modalbox\"><button class=\"close\" onclick=\"closeModal()\">\u00d7</button><div id=\"modalContent\"></div></div></div><div id=\"toast\" class=\"toast\"></div>\n<script>\nlet profiles=JSON.parse(localStorage.getItem('glamourProfiles')||'null')||[\n{name:\"Sienna\",city:\"Bangkok\",nat:\"International\",type:\"VIP\",price:\"mid\",amount:200,age:26,image:\"data:image/jpeg;base64,\",about:\"A polished premium profile with a warm introduction and clear profile information.\",services:[\"Events\",\"Travel\",\"Dining\",\"Companionship\"],reviews:[\"Very professional and friendly.\",\"Elegant profile and great communication.\"]},\n{name:\"Ava\",city:\"Phuket\",nat:\"Thai\",type:\"VIP\",price:\"high\",amount:300,age:24,image:\"data:image/jpeg;base64,\",about:\"A verified premium profile with interests, availability and profile details.\",services:[\"Events\",\"Travel\",\"Dining\",\"Social\"],reviews:[\"Excellent communication.\",\"A very polished experience.\"]},\n{name:\"Lily\",city:\"Pattaya\",nat:\"International\",type:\"VIP\",price:\"mid\",amount:200,age:25,image:\"data:image/jpeg;base64,\",about:\"A premium profile with verified account information and selectable services.\",services:[\"Events\",\"Dining\",\"Travel\",\"Custom\"],reviews:[\"Very kind and professional.\",\"Clear communication and lovely profile.\"]}\n];\nlocalStorage.setItem('glamourProfiles',JSON.stringify(profiles));\nfunction card(p){return `<article class=\"card\"><div class=\"photo\" style=\"background-image:url('${p.image}')\"><div class=\"badges\"><span class=\"badge verified\">\u2713 Verified</span><span class=\"badge vip\">\u265b VIP</span></div></div><div class=\"body\"><h3 class=\"name\">${p.name}</h3><div class=\"meta\">\u2316 ${p.city} \u2022 ${p.nat} \u2022 ${p.age}</div><div class=\"price\">${p.type || \"Standard\"} profile</div><p class=\"about\">${p.about}</p><div class=\"services\">${p.services.map(x=>`<span class=\"service\">${x}</span>`).join(\"\")}</div><div class=\"actions\"><button class=\"btn\" onclick=\"openProfile('${p.name}')\">View Profile</button></div></div></article>`}\nfunction dedupeProfiles(list){\n const seen=new Set(),out=[];\n for(const p of (list||[])){\n   const key=p.id ? \"id:\"+p.id : \"name:\"+String(p.name||\"\").trim().toLowerCase();\n   if(seen.has(key)) continue;\n   seen.add(key); out.push(p);\n }\n return out;\n}\nconst STARTER_IMAGE_BY_NAME={};\nprofiles.forEach(p=>{if(p&&p.name&&p.image)STARTER_IMAGE_BY_NAME[String(p.name).trim().toLowerCase()]=p.image;});\nprofiles=dedupeProfiles(profiles);\nfunction render(list,id){\n const unique=dedupeProfiles(list);\n document.getElementById(id).innerHTML=unique.map(card).join(\"\")||\"<p class='muted'>No profiles found.</p>\";\n}\nrender(profiles.slice(0,3),\"featured\");render(profiles,\"all\");render(profiles.filter(x=>x.type===\"VIP\"),\"vips\");\nfunction page(id){document.querySelectorAll(\".page\").forEach(x=>x.classList.remove(\"active\"));document.getElementById(id).classList.add(\"active\");if(id===\"pricing\")loadPaymentProfiles();scrollTo(0,0)}document.addEventListener(\"click\",e=>{let b=e.target.closest(\"[data-page]\");if(b)page(b.dataset.page)});\nfunction openProfile(n){\n  let p=profiles.find(x=>x.name===n);\n  document.getElementById(\"modalContent\").innerHTML=`\n  <div class=\"detail-photo\" style=\"background-image:url('${p.image}')\"></div>\n  <div style=\"padding-top:16px\">\n    <span class=\"badge verified\">\u2713 Verified</span><span class=\"badge vip\">\u265b VIP</span>\n    <h2 style=\"font:38px Georgia;margin:12px 0 6px\">${p.name}</h2>\n    <p class=\"muted\">\u2316 ${p.city} \u2022 ${p.nat} \u2022 Age ${p.age}</p>\n    <div class=\"price\">${p.type || \"Standard\"} profile</div>\n    <div style=\"display:flex;gap:6px;border-bottom:1px solid #302a1f;margin:16px 0 12px\">\n      <button class=\"tabbtn active\" onclick=\"showTab('about',this)\">About</button>\n      <button class=\"tabbtn\" onclick=\"showTab('services',this)\">Services</button>\n      <button class=\"tabbtn\" onclick=\"showTab('reviews',this)\">Reviews</button>\n    </div>\n    <div id=\"aboutTab\"><h3>About</h3><p>${p.about}</p></div>\n    <div id=\"servicesTab\" style=\"display:none\"><h3>Services</h3><div class=\"services\">${p.services.map(x=>`<span class=\"service\">${x}</span>`).join(\"\")}</div></div>\n    <div id=\"reviewsTab\" style=\"display:none\"><h3>Reviews</h3>${p.reviews.map(x=>`<div style=\"padding:11px 0;border-bottom:1px solid #28251e\"><span style=\"color:#e5c55f\">\u2605\u2605\u2605\u2605\u2605</span><p class=\"muted\">${x}</p></div>`).join(\"\")}<br><button class=\"btn\" onclick=\"toast('Review form ready for backend')\">Write a Review</button></div>\n    \n  </div>`;\n  document.getElementById(\"modal\").classList.add(\"show\")\n}\nfunction showTab(which,el){\n  document.getElementById(\"aboutTab\").style.display=which===\"about\"?\"block\":\"none\";\n  document.getElementById(\"servicesTab\").style.display=which===\"services\"?\"block\":\"none\";\n  document.getElementById(\"reviewsTab\").style.display=which===\"reviews\"?\"block\":\"none\";\n  document.querySelectorAll(\".tabbtn\").forEach(x=>x.classList.remove(\"active\"));el.classList.add(\"active\");\n}\nfunction closeModal(){document.getElementById(\"modal\").classList.remove(\"show\")}function toast(s){let t=document.getElementById(\"toast\");t.textContent=s;t.classList.add(\"show\");setTimeout(()=>t.classList.remove(\"show\"),2200)}\nlogin.onclick=()=>{\n document.getElementById(\"modalContent\").innerHTML=\"<h2>Owner Login</h2><p class='muted'>Use the owner account created in Supabase Authentication.</p><input placeholder='Email' id='loginEmail' style='width:100%;padding:12px;background:#111;color:#fff;border:1px solid #4a3b18;border-radius:7px'><br><br><input type='password' placeholder='Password' id='loginPassword' style='width:100%;padding:12px;background:#111;color:#fff;border:1px solid #4a3b18;border-radius:7px'><br><br><button class='btn gold' onclick='realOwnerLogin()'>Sign In</button><div id='loginMsg' class='muted' style='margin-top:10px'></div>\";\n document.getElementById(\"modal\").classList.add(\"show\")\n}\nsignup.onclick=()=>{document.getElementById(\"modalContent\").innerHTML=\"<h2>Create Account</h2><input placeholder='Email' style='width:100%;padding:12px;background:#111;color:#fff;border:1px solid #4a3b18;border-radius:7px'><br><br><button class='btn gold' onclick='closeModal()'>Create Account</button>\";document.getElementById(\"modal\").classList.add(\"show\")}\nsearchBtn.onclick=()=>{let c=city.value,n=nat.value,t=type.value,pr=price.value,q=query.value.toLowerCase();render(profiles.filter(p=>(!c||p.city===c)&&(!n||p.nat===n)&&(!t||p.type===t)&&(!pr||(pr==='high'?p.type==='VIP':pr==='mid'?p.type==='Premium':true))&&(!q||p.name.toLowerCase().includes(q))),\"all\");page(\"profiles\")}\n\nasync function loadPaymentProfiles(){\n  const wrap=document.getElementById('paymentProfileWrap'); if(!wrap) return;\n  if(!window.glamourDB){wrap.innerHTML='<div class=\"production-status\">Database connection required.</div>';return;}\n  const {data:{user}}=await glamourDB.auth.getUser();\n  if(!user){wrap.innerHTML='<div class=\"production-status\">Please <button class=\"btn gold\" onclick=\"login.click()\">sign in</button> first.</div>';return;}\n  const {data,error}=await glamourDB.from('profiles').select('id,name,plan,plan_expires_at').eq('owner_id',user.id).order('created_at',{ascending:false});\n  if(error){wrap.innerHTML='<div class=\"production-status\">Could not load profiles: '+error.message+'</div>';return;}\n  if(!data?.length){wrap.innerHTML='<div class=\"production-status\">Create or sync a profile first.</div>';return;}\n  wrap.innerHTML='<label class=\"muted\">Profile to upgrade</label><select id=\"paymentProfile\" class=\"plan-select\">'+data.map(x=>`<option value=\"${x.id}\">${x.name} \u2014 ${(x.plan||'basic').toUpperCase()}</option>`).join('')+'</select>';\n}\nasync function buyPlan(plan){\n  if(!window.glamourDB){toast('Database is not connected');return;}\n  const profileId=document.getElementById('paymentProfile')?.value;\n  if(!profileId){toast('Select a profile first');return;}\n  toast('Opening secure Stripe Checkout\u2026');\n  const {data:{session}}=await glamourDB.auth.getSession();\n  if(!session?.access_token){toast('Please sign in again');return;}\n  const response=await fetch('/api/stripe/checkout',{\n    method:'POST',\n    headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token},\n    body:JSON.stringify({plan,profile_id:profileId})\n  });\n  const data=await response.json().catch(()=>({}));\n  if(!response.ok){toast('Checkout error: '+(data.error||'Payment service unavailable'));return;}\n  if(data?.url) location.href=data.url; else toast('Checkout URL was not returned');\n}\nasync function setBasicPlan(){\n  if(!window.glamourDB){toast('Database is not connected');return;}\n  const profileId=document.getElementById('paymentProfile')?.value;\n  if(!profileId){toast('Select a profile first');return;}\n  const {error}=await glamourDB.from('profiles').update({plan:'basic',vip:false,plan_expires_at:null,updated_at:new Date().toISOString()}).eq('id',profileId);\n  if(error){toast('Could not activate Basic: '+error.message);return;}\n  toast('Basic plan activated'); await refreshProfilesFromSupabase(); loadPaymentProfiles();\n}\n\nfunction renderAdmin(){\n const box=document.getElementById(\"adminList\");\n box.innerHTML=`<div class=\"admin-grid\">${profiles.map((p,i)=>`\n <article class=\"admin-card\">\n   <div class=\"admin-photo-wrap\">\n     <img class=\"admin-photo\" src=\"${p.image}\" alt=\"${p.name}\" onerror=\"this.style.display='none';this.nextElementSibling.style.display='flex'\">\n     <div class=\"admin-photo-fallback\">GLAMOUR LUXE</div>\n     <div class=\"admin-badges\"><span class=\"badge verified\">\u2713 Verified</span>${p.type==='VIP'?'<span class=\"badge vip\">\u2605 VIP</span>':''}</div>\n   </div>\n   <div class=\"admin-body\">\n     <div class=\"admin-title-row\"><div><h3>${p.name}</h3><div class=\"muted\">${p.city} \u00b7 ${p.nat}</div></div><div class=\"admin-status\">ACTIVE</div></div>\n     <div class=\"admin-fields\">\n       <label>Name<input id=\"a_name_${i}\" value=\"${p.name}\" placeholder=\"Name\"></label>\n       <label>City<input id=\"a_city_${i}\" value=\"${p.city}\" placeholder=\"City\"></label>\n       <label>Nationality<input id=\"a_nat_${i}\" value=\"${p.nat}\" placeholder=\"Nationality\"></label>\n       <label>Price<input id=\"a_price_${i}\" type=\"number\" value=\"${p.amount}\" placeholder=\"Price\"></label>\n       <label class=\"full\">About<textarea id=\"a_about_${i}\" placeholder=\"About\">${p.about}</textarea></label>\n     </div>\n     <div class=\"admin-actions\"><button class=\"btn gold\" onclick=\"saveAdmin(${i})\">Save Changes</button><button class=\"btn\" onclick=\"openProfile(profiles[${i}].name)\">Preview Profile</button></div>\n   </div>\n </article>`).join(\"\")}</div>`;\n}\nasync function saveAdmin(i){\n  let p=profiles[i];\n  if(!p){toast(\"Profile not found\");return}\n  const name=document.getElementById(\"a_name_\"+i).value.trim()||p.name;\n  const city=document.getElementById(\"a_city_\"+i).value.trim()||p.city;\n  const nat=document.getElementById(\"a_nat_\"+i).value.trim()||p.nat;\n  const amount=Number(document.getElementById(\"a_price_\"+i).value)||p.amount;\n  const about=document.getElementById(\"a_about_\"+i).value.trim()||p.about;\n\n  if(!window.glamourDB){toast(\"Supabase is not connected\");return}\n  const {data:{user}}=await glamourDB.auth.getUser();\n  if(!user){toast(\"Please sign in first\");return}\n\n  if(!p.id){\n    const {data:existing,error:readError}=await glamourDB.from(\"profiles\")\n      .select(\"*\").eq(\"owner_id\",user.id);\n    if(readError){toast(\"Database read failed: \"+readError.message);return}\n    const match=(existing||[]).find(x=>String(x.name||\"\").toLowerCase()===String(p.name||\"\").toLowerCase());\n    if(match){p.id=match.id}\n    else{\n      const {data:created,error:createError}=await glamourDB.from(\"profiles\").insert({\n        owner_id:user.id,name:p.name,city:p.city||\"\",nationality:p.nat||\"\",\n        about:p.about||\"\",price:Number(p.amount)||0,currency:\"USD\",\n        verified:true,vip:p.type===\"VIP\",active:true,\n        photo_urls:(p.image && String(p.image).startsWith(\"http\"))?[p.image]:[]\n      }).select().single();\n      if(createError){toast(\"Database create failed: \"+createError.message);return}\n      p.id=created.id;\n    }\n  }\n\n  const {data,error}=await glamourDB.from(\"profiles\").update({\n    name,city,nationality:nat,price:amount,about,updated_at:new Date().toISOString()\n  }).eq(\"id\",p.id).eq(\"owner_id\",user.id).select().single();\n\n  if(error){toast(\"Database save failed: \"+error.message);return}\n  p.name=data.name;p.city=data.city||\"\";p.nat=data.nationality||\"\";\n  p.amount=data.price||amount;p.about=data.about||\"\";\n  localStorage.setItem(\"glamourProfiles\",JSON.stringify(profiles));\n  render(dedupeProfiles(profiles).slice(0,3),\"featured\");render(dedupeProfiles(profiles),\"all\");render(dedupeProfiles(profiles.filter(x=>x.type===\"VIP\")),\"vips\");\n  renderAdmin();toast(\"\u2713 Saved to Supabase\");\n}\nasync function refreshProfilesFromSupabase(){\n if(!window.glamourDB) return false;\n try{\n   const {data:rows,error}=await glamourDB.from(\"profiles\").select(\"*\").eq(\"active\",true).order(\"created_at\",{ascending:false});\n   if(error) throw error;\n   if(!rows || !rows.length) return false;\n   profiles=dedupeProfiles(rows.map(p=>({\n     id:p.id,name:p.name,city:p.city||\"\",nat:p.nationality||\"\",amount:p.price||0,\n     age:26,type:p.vip?\"VIP\":\"Standard\",price:(Number(p.price)||0)>=300?\"high\":\"mid\",\n     image:(p.photo_urls&&p.photo_urls[0]) || STARTER_IMAGE_BY_NAME[String(p.name||\"\").trim().toLowerCase()] || \"\",\n     about:p.about||\"\",services:[],reviews:[]\n   })));\n   localStorage.setItem(\"glamourProfiles\",JSON.stringify(profiles));\n   render(profiles.slice(0,3),\"featured\");render(profiles,\"all\");render(profiles.filter(x=>x.type===\"VIP\"),\"vips\");\n   if(document.getElementById(\"adminList\")) renderAdmin();\n   return true;\n }catch(e){console.warn(\"Supabase profile load failed\",e);return false}\n}\nasync function realOwnerLogin(){\n const msg=document.getElementById(\"loginMsg\");\n const email=(document.getElementById(\"loginEmail\")||{}).value?.trim();\n const password=(document.getElementById(\"loginPassword\")||{}).value||\"\";\n if(!window.glamourDB){msg.textContent=\"Supabase is not connected.\";return}\n if(!email||!password){msg.textContent=\"Enter email and password.\";return}\n msg.textContent=\"Signing in\u2026\";\n const {data,error}=await glamourDB.auth.signInWithPassword({email,password});\n if(error){msg.textContent=error.message;return}\n const user=data.user;\n const {data:roleRow,error:roleError}=await glamourDB.from(\"user_roles\").select(\"role\").eq(\"user_id\",user.id).maybeSingle();\n if(roleError || !roleRow || ![\"owner\",\"admin\"].includes(roleRow.role)){\n   await glamourDB.auth.signOut();\n   msg.textContent=\"This account is not authorized for the admin panel.\";\n   return;\n }\n document.getElementById(\"adminBtn\").style.display=\"inline-block\";\n closeModal(); await refreshProfilesFromSupabase(); page(\"admin\"); renderAdmin(); toast(\"Secure admin access granted\");\n}\n\nasync function syncDemoProfilesToSupabase(){\n  if(!window.glamourDB){toast(\"Supabase is not connected\");return false}\n  const {data:{user}}=await glamourDB.auth.getUser();\n  if(!user){toast(\"Sign in as owner first\");return false}\n\n  const {data:existing,error:readError}=await glamourDB\n    .from(\"profiles\")\n    .select(\"*\")\n    .eq(\"owner_id\",user.id);\n\n  if(readError){toast(\"Database read failed: \"+readError.message);return false}\n\n  const byName=new Map((existing||[]).map(row=>[String(row.name||\"\").toLowerCase(),row]));\n  const saved=[];\n\n  for(const p of profiles){\n    const old=byName.get(String(p.name||\"\").toLowerCase());\n    const record={\n      ...(old?.id ? {id:old.id} : {}),\n      owner_id:user.id,\n      name:p.name,\n      city:p.city||\"\",\n      nationality:p.nat||\"\",\n      about:p.about||\"\",\n      price:Number(p.amount)||0,\n      currency:\"USD\",\n      verified:true,\n      vip:p.type===\"VIP\",\n      active:true,\n      photo_urls:(old?.photo_urls && old.photo_urls.length) ? old.photo_urls : []\n    };\n\n    const result=old?.id\n      ? await glamourDB.from(\"profiles\").update(record).eq(\"id\",old.id).select().single()\n      : await glamourDB.from(\"profiles\").insert(record).select().single();\n\n    if(result.error){\n      toast(\"Profile sync failed: \"+result.error.message);\n      return false;\n    }\n    saved.push(result.data);\n  }\n\n  profiles=saved.map(p=>({\n    id:p.id,\n    name:p.name,\n    city:p.city||\"\",\n    nat:p.nationality||\"\",\n    amount:p.price||0,\n    age:26,\n    type:p.vip?\"VIP\":\"Standard\",\n    price:\"mid\",\n    image:(p.photo_urls||[])[0]||\"\",\n    about:p.about||\"\",\n    services:[],\n    reviews:[]\n  }));\n\n  localStorage.setItem(\"glamourProfiles\",JSON.stringify(profiles));\n  render(profiles,\"featured\");\n  render(profiles,\"all\");\n  render(profiles.filter(x=>x.type===\"VIP\"),\"vips\");\n  renderAdmin();\n  toast(\"\u2713 Profiles synced to Supabase\");\n  return true;\n}\n</script><script>\ndocument.addEventListener(\"DOMContentLoaded\", async () => {\n  const status = document.createElement(\"div\");\n  status.id = \"dbStatus\";\n  status.style.cssText=\"position:fixed;bottom:14px;right:14px;z-index:9999;padding:9px 12px;border:1px solid #d4af37;border-radius:10px;background:#080808;color:#d4af37;font:12px Arial\";\n  status.textContent = (window.glamourDB ? \"\u25cf Supabase connected\" : \"\u25cb Database connection not configured\");\n  document.body.appendChild(status);\n  if(window.glamourDB){\n    await refreshProfilesFromSupabase();\n    status.textContent=\"\u25cf Supabase connected\";\n    const mode=document.getElementById(\"adminModeText\");\n    if(mode) mode.textContent=\"Secure owner panel. Changes are saved directly to Supabase.\";\n  }\n});\n</script>\n\n\n<style id=\"glamour-final-status\">\n#glamour-final-status{position:fixed;right:14px;bottom:14px;z-index:99999;padding:9px 12px;border:1px solid #d4af37;border-radius:12px;background:#070707;color:#d4af37;font:12px Arial;box-shadow:0 0 18px #000}\n</style>\n<script id=\"glamour-final-status-script\">\ndocument.addEventListener(\"DOMContentLoaded\",function(){\n  loadPaymentProfiles();\n  var el=document.createElement(\"div\");\n  el.id=\"glamour-final-status\";\n  el.textContent=window.glamourDB ? \"\u25cf Production database connected\" : \"\u25cb Database connection not configured\";\n  document.body.appendChild(el);\n});\n</script>\n\n\n<script id=\"glamour-db-bootstrap\">\ndocument.addEventListener(\"DOMContentLoaded\", async function(){\n  if(!window.glamourDB) return;\n  try{\n    const {data:{user}}=await glamourDB.auth.getUser();\n    if(!user) return;\n    const {data:rows}=await glamourDB.from(\"profiles\").select(\"id\").eq(\"owner_id\",user.id).limit(1);\n    if(!rows || rows.length===0){\n      if(typeof syncDemoProfilesToSupabase===\"function\") await syncDemoProfilesToSupabase();\n    }else{\n      await refreshProfilesFromSupabase();\n    }\n  }catch(e){console.warn(\"GLAMOUR DB bootstrap\",e)}\n});\n</script>\n\n\n<script id=\"glamour-auto-bootstrap\">\ndocument.addEventListener(\"DOMContentLoaded\",async function(){\n  if(!window.glamourDB) return;\n  const loaded=await refreshProfilesFromSupabase();\n  if(!loaded){\n    try{\n      const {data:{user}}=await glamourDB.auth.getUser();\n      if(user && typeof syncDemoProfilesToSupabase===\"function\") await syncDemoProfilesToSupabase();\n    }catch(e){console.warn(\"GLAMOUR bootstrap\",e)}\n  }\n  const badge=document.getElementById(\"dbStatus\");\n  if(badge) badge.textContent=\"\u25cf Production database connected\";\n});\n</script>\n\n<script id=\"glamour-stripe-confirm\">\ndocument.addEventListener(\"DOMContentLoaded\", async function(){\n  const params=new URLSearchParams(location.search);\n  if(params.get(\"payment\")!==\"success\" || !params.get(\"session_id\") || !window.glamourDB) return;\n  try{\n    const {data:{session}}=await glamourDB.auth.getSession();\n    if(!session?.access_token){toast(\"Payment returned. Please sign in again to confirm it.\");return;}\n    const r=await fetch('/api/stripe/confirm?session_id='+encodeURIComponent(params.get(\"session_id\")),{headers:{Authorization:'Bearer '+session.access_token}});\n    const data=await r.json().catch(()=>({}));\n    if(!r.ok){toast('Payment confirmation: '+(data.error||'Could not confirm payment'));return;}\n    await refreshProfilesFromSupabase(); await loadPaymentProfiles();\n    toast('\u2713 '+String(data.plan||'Plan').toUpperCase()+' activated for 30 days');\n    history.replaceState({},document.title,location.pathname);\n  }catch(e){toast('Payment confirmation error: '+(e?.message||e));}\n});\n</script>\n</body></html>";
const GLAMOUR_SUPABASE_URL = "https://ifxpcofseejzobrueqvs.supabase.co";
const GLAMOUR_SUPABASE_PUBLISHABLE_KEY = "sb_publishable_RBXrPe56Z76WP0b6wnzVDA_-w8QJX7bP";
const GLAMOUR_WORKER_ORIGIN = "https://glamour-luxe.axrarovabaxor93.workers.dev";

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      "access-control-allow-origin": "*",
      "access-control-allow-methods": "GET,POST,OPTIONS",
      "access-control-allow-headers": "content-type,authorization"
    }
  });
}

function formBody(obj) {
  return Object.entries(obj)
    .filter(([, value]) => value !== undefined && value !== null)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");
}

async function supabaseUser(request, env) {
  const auth = request.headers.get("Authorization");
  if (!auth?.startsWith("Bearer ")) return null;
  const r = await fetch(`${GLAMOUR_SUPABASE_URL}/auth/v1/user`, {
    headers: {
      apikey: GLAMOUR_SUPABASE_PUBLISHABLE_KEY,
      Authorization: auth
    }
  });
  if (!r.ok) return null;
  return await r.json();
}

async function createCheckout(request, env) {
  if (!env.STRIPE_SECRET_KEY) return json({ ok: false, error: "Stripe secret key is not configured." }, 503);
  const user = await supabaseUser(request, env);
  if (!user?.id) return json({ ok: false, error: "Authentication required." }, 401);
  let body;
  try { body = await request.json(); } catch { return json({ ok: false, error: "Invalid request body." }, 400); }
  const plan = body?.plan, profileId = body?.profile_id;
  if (!['premium', 'vip'].includes(plan) || !profileId) return json({ ok: false, error: "Invalid plan or profile." }, 400);

  const profileResponse = await fetch(`${GLAMOUR_SUPABASE_URL}/rest/v1/profiles?id=eq.${encodeURIComponent(profileId)}&owner_id=eq.${encodeURIComponent(user.id)}&select=id,name,owner_id`, {
    headers: { apikey: GLAMOUR_SUPABASE_PUBLISHABLE_KEY, Authorization: `Bearer ${userToken(request)}` }
  });
  if (!profileResponse.ok) {
    const detail = await profileResponse.text().catch(() => "");
    return json({ ok: false, error: `Profile verification failed (${profileResponse.status}).${detail ? ` ${detail.slice(0, 500)}` : ""}` }, 400);
  }
  const profiles = await profileResponse.json();
  if (!profiles?.length) return json({ ok: false, error: "Profile not found or not owned by this account." }, 404);

  const priceId = plan === 'vip'
    ? 'price_1UMmISG8lGvV5X1a7eOgOIQR'
    : 'price_1UMmGKG8lGvV5X1a9aYozK74';
  const stripeResponse = await fetch("https://api.stripe.com/v1/checkout/sessions", {
  method: "POST",
  headers: {
    "Authorization": `Bearer ${env.STRIPE_SECRET_KEY}`,
    "Content-Type": "application/x-www-form-urlencoded" 
  },
  body: new URLSearchParams({
    "mode": "payment",
    "success_url": `${origin}/payment?success=success&session_id={CHECKOUT_SESSION_ID}`,
    "cancel_url": `${origin}/payment?cancelled`,
    "line_items[0][price]": priceId,
    "line_items[0][quantity]": "1",
    "client_reference_id": profileId,
    "metadata[profile_id]": profileId,
    "metadata[user_id]": user.id,
    "metadata[plan]": plan,
    "payment_intent_data[metadata][profile_id]": profileId,
    "payment_intent_data[metadata][user_id]": user.id,
    "payment_intent_data[metadata][plan]": plan
  })
});

  const stripeData = await stripeResponse.json();
  if (!stripeResponse.ok) return json({ ok: false, error: stripeData?.error?.message || "Stripe Checkout failed." }, 400);
  return json({ ok: true, url: stripeData.url, session_id: stripeData.id });
}

function userToken(request) {
  const auth = request.headers.get("Authorization");
  return auth?.startsWith("Bearer ") ? auth.slice(7) : "";
}

async function confirmCheckout(request, env) {
  if (!env.STRIPE_SECRET_KEY) return json({ ok: false, error: "Stripe secret key is not configured." }, 503);
  const user = await supabaseUser(request, env);
  if (!user?.id) return json({ ok: false, error: "Authentication required." }, 401);
  const sessionId = new URL(request.url).searchParams.get("session_id");
  if (!sessionId) return json({ ok: false, error: "Missing Checkout session ID." }, 400);

  const stripeResponse = await fetch(`https://api.stripe.com/v1/checkout/sessions/${encodeURIComponent(sessionId)}`, {
    headers: { Authorization: `Bearer ${env.STRIPE_SECRET_KEY}` }
  });
  const session = await stripeResponse.json();
  if (!stripeResponse.ok) return json({ ok: false, error: session?.error?.message || "Could not verify Stripe session." }, 400);
  if (session.payment_status !== "paid") return json({ ok: false, error: "Payment has not been completed." }, 402);

  const meta = session.metadata || {};
  if (meta.user_id !== user.id) return json({ ok: false, error: "Payment session does not belong to this account." }, 403);
  if (!['premium', 'vip'].includes(meta.plan) || !meta.profile_id) return json({ ok: false, error: "Invalid payment metadata." }, 400);

  const expires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();
  const update = await fetch(`${GLAMOUR_SUPABASE_URL}/rest/v1/profiles?id=eq.${encodeURIComponent(meta.profile_id)}&owner_id=eq.${encodeURIComponent(user.id)}`, {
    method: "PATCH",
    headers: { apikey: GLAMOUR_SUPABASE_PUBLISHABLE_KEY, Authorization: `Bearer ${userToken(request)}`, "Content-Type": "application/json", Prefer: "return=minimal" },
    body: JSON.stringify({ plan: meta.plan, vip: meta.plan === "vip", plan_expires_at: expires, active: true, updated_at: new Date().toISOString() })
  });
  if (!update.ok) return json({ ok: false, error: "Payment was received, but the profile could not be updated." }, 500);
  return json({ ok: true, plan: meta.plan, profile_id: meta.profile_id, expires_at: expires });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS") return new Response(null, {
      status: 204,
      headers: {
        "access-control-allow-origin": "*",
        "access-control-allow-methods": "GET,POST,OPTIONS",
        "access-control-allow-headers": "content-type,authorization"
      }
    });

    if (url.pathname === "/api/health") {
      let supabase = "configured";
      try {
        const r = await fetch(`${GLAMOUR_SUPABASE_URL}/rest/v1/`, { headers: { apikey: GLAMOUR_SUPABASE_PUBLISHABLE_KEY } });
        supabase = r.ok ? "reachable" : `http-${r.status}`;
      } catch (e) { supabase = `error:${e?.message || String(e)}`; }
      let stripe = "missing-secret";
      if (env.STRIPE_SECRET_KEY) {
        try {
          const r = await fetch("https://api.stripe.com/v1/prices/price_1UMmGKG8lGvV5X1a9aYozK74", { headers: { Authorization: `Bearer ${env.STRIPE_SECRET_KEY}` } });
          stripe = r.ok ? "reachable" : `http-${r.status}`;
        } catch (e) { stripe = `error:${e?.message || String(e)}`; }
      }
      return json({ ok: true, service: "GLAMOUR LUXE", stripe, supabase, origin: GLAMOUR_WORKER_ORIGIN });
    }

    if (url.pathname === "/api/stripe/checkout" && request.method === "POST") {
      try { return await createCheckout(request, env); }
      catch (e) { return json({ ok: false, error: e?.message || String(e) }, 500); }
    }

    if (url.pathname === "/api/stripe/confirm" && request.method === "GET") {
      try { return await confirmCheckout(request, env); }
      catch (e) { return json({ ok: false, error: e?.message || String(e) }, 500); }
    }

    if (url.pathname.startsWith("/api/")) return json({ ok: false, error: "API route not found" }, 404);

    let response;
    if (url.pathname === "/" || url.pathname === "/index.html") {
      response = new Response(INDEX_HTML, { headers: { "content-type": "text/html; charset=utf-8" } });
    } else if (env.ASSETS) {
      response = await env.ASSETS.fetch(request);
    } else {
      return new Response("Not Found", { status: 404 });
    }
    const headers = new Headers(response.headers);
    headers.set("X-Content-Type-Options", "nosniff");
    headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
    headers.set("X-GLAMOUR-LUXE", "active");
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
  }
};

